using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.AspNetCore.RateLimiting;
namespace Salao.Api.Controllers;
[ApiController, Route("api")]
public class SalonController(SalonDb db) : ControllerBase {
 private static DateTime BrazilDayStartUtc(DateOnly date)=>new DateTimeOffset(date.ToDateTime(TimeOnly.MinValue),TimeSpan.FromHours(-3)).UtcDateTime;
 private async Task<bool> HasAdminChangeCode(){var code=Request.Headers["X-Admin-Change-Code"].ToString();var credential=await db.AdminCredentials.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==1);return credential is not null&&AdminCodeHash.Verify(code,credential.ChangeCodeHash);}
 private bool IsAdmin=>HttpContext.Items.ContainsKey("SalonAdmin");
 private SalonUser? CurrentSalonUser=>HttpContext.Items["SalonUser"] as SalonUser;
 private async Task<bool> HasCatalogMutationAuthorization(){if(IsAdmin)return await HasAdminChangeCode();var user=CurrentSalonUser;if(user is null||(!user.CanManageCatalog&&!user.CanChangePrices)||user.ChangeCodeHash is null)return false;return AdminCodeHash.Verify(Request.Headers["X-Admin-Change-Code"].ToString(),user.ChangeCodeHash);}
 private async Task<bool> HasCurrentUserAccessCode(){var code=Request.Headers["X-User-Access-Code"].ToString();if(!System.Text.RegularExpressions.Regex.IsMatch(code,@"^\d{6}$"))return false;if(IsAdmin){var credential=await db.AdminCredentials.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==1);return credential is not null&&AdminCodeHash.Verify(code,credential.AccessCodeHash);}var user=CurrentSalonUser;return user is not null&&AdminCodeHash.Verify(code,user.AccessCodeHash);}
 private bool CanManageCatalog=>IsAdmin||CurrentSalonUser?.CanManageCatalog==true;
 private bool CanChangePrices=>IsAdmin||CurrentSalonUser?.CanChangePrices==true;
 [HttpPost("admin/login"),EnableRateLimiting("admin-login")] public async Task<IActionResult> Login([FromBody]AdminAccessInput input){var credential=await db.AdminCredentials.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==1);if(credential is not null&&AdminCodeHash.Verify(input.AccessCode,credential.AccessCodeHash))return Ok(new{token=AdminSessionTokens.Create(credential),expiresInSeconds=43200,role="admin",name="Administradora",canManageCatalog=true,canChangePrices=true});var users=await db.SalonUsers.AsNoTracking().Where(x=>x.Active).ToListAsync();var user=users.FirstOrDefault(x=>AdminCodeHash.Verify(input.AccessCode,x.AccessCodeHash));return user is null?Unauthorized(new{message="Código de acesso incorreto."}):Ok(new{token=SalonUserSessions.Create(user),expiresInSeconds=43200,role="staff",name=user.Name,canManageCatalog=user.CanManageCatalog,canChangePrices=user.CanChangePrices});}
 [HttpGet("admin/users")] public async Task<IActionResult> Users(){if(!IsAdmin)return Forbid();return Ok(await db.SalonUsers.OrderBy(x=>x.Name).Select(x=>new{id=x.Id,x.Name,x.CanManageCatalog,x.CanChangePrices,x.Active,x.CreatedAt}).ToListAsync());}
 [HttpPost("admin/users")] public async Task<IActionResult> CreateUser([FromBody]CreateSalonUserInput input){if(!IsAdmin)return Forbid();if(string.IsNullOrWhiteSpace(input.Name)||!System.Text.RegularExpressions.Regex.IsMatch(input.AccessCode,@"^\d{6}$"))return BadRequest("Informe o nome e um código de acesso com 6 dígitos.");if(input.CanManageCatalog||input.CanChangePrices){if(string.IsNullOrWhiteSpace(input.ChangeCode)||!System.Text.RegularExpressions.Regex.IsMatch(input.ChangeCode,@"^\d{4}$"))return BadRequest("Defina um código de confirmação de 4 dígitos para liberar alterações no catálogo.");}var admin=await db.AdminCredentials.AsNoTracking().SingleAsync(x=>x.Id==1);if(AdminCodeHash.Verify(input.AccessCode,admin.AccessCodeHash))return Conflict("Este código já está sendo usado.");var existing=await db.SalonUsers.AsNoTracking().ToListAsync();if(existing.Any(x=>AdminCodeHash.Verify(input.AccessCode,x.AccessCodeHash)))return Conflict("Este código já está sendo usado por outro usuário.");var user=new SalonUser{Name=input.Name.Trim(),AccessCodeHash=AdminCodeHash.Create(input.AccessCode),ChangeCodeHash=(input.CanManageCatalog||input.CanChangePrices)?AdminCodeHash.Create(input.ChangeCode!):null,SessionKey=AdminSessionTokens.NewSigningKey(),CanManageCatalog=input.CanManageCatalog,CanChangePrices=input.CanChangePrices,Active=true,CreatedAt=DateTime.UtcNow};db.SalonUsers.Add(user);await db.SaveChangesAsync();return Created($"/api/admin/users/{user.Id}",new{id=user.Id,user.Name,user.CanManageCatalog,user.CanChangePrices,user.Active,user.CreatedAt});}
 [HttpPatch("admin/users/{id:long}")] public async Task<IActionResult> UpdateUser(long id,[FromBody]UpdateSalonUserInput input){if(!IsAdmin)return Forbid();var user=await db.SalonUsers.FindAsync(id);if(user is null)return NotFound();if(string.IsNullOrWhiteSpace(input.Name))return BadRequest("Informe o nome do usuário.");if(!string.IsNullOrEmpty(input.AccessCode)){if(!System.Text.RegularExpressions.Regex.IsMatch(input.AccessCode,@"^\d{6}$"))return BadRequest("O código de acesso deve ter 6 dígitos.");var admin=await db.AdminCredentials.AsNoTracking().SingleAsync(x=>x.Id==1);if(AdminCodeHash.Verify(input.AccessCode,admin.AccessCodeHash))return Conflict("Este código já está sendo usado.");var others=await db.SalonUsers.AsNoTracking().Where(x=>x.Id!=id).ToListAsync();if(others.Any(x=>AdminCodeHash.Verify(input.AccessCode,x.AccessCodeHash)))return Conflict("Este código já está sendo usado.");user.AccessCodeHash=AdminCodeHash.Create(input.AccessCode);}
  var needsChangeCode=input.CanManageCatalog||input.CanChangePrices;if(needsChangeCode&&!string.IsNullOrEmpty(input.ChangeCode)){if(!System.Text.RegularExpressions.Regex.IsMatch(input.ChangeCode,@"^\d{4}$"))return BadRequest("O código de confirmação deve ter 4 dígitos.");user.ChangeCodeHash=AdminCodeHash.Create(input.ChangeCode);}else if(needsChangeCode&&user.ChangeCodeHash is null)return BadRequest("Defina um código de confirmação de 4 dígitos para liberar alterações no catálogo.");else if(!needsChangeCode)user.ChangeCodeHash=null;
  user.Name=input.Name.Trim();user.CanManageCatalog=input.CanManageCatalog;user.CanChangePrices=input.CanChangePrices;user.Active=input.Active;user.SessionKey=AdminSessionTokens.NewSigningKey();await db.SaveChangesAsync();return Ok(new{id=user.Id,user.Name,user.CanManageCatalog,user.CanChangePrices,user.Active,user.CreatedAt});}
 [HttpDelete("admin/users/{id:long}")] public async Task<IActionResult> DeleteUser(long id){if(!IsAdmin)return Forbid();var user=await db.SalonUsers.FindAsync(id);if(user is null)return NotFound();db.SalonUsers.Remove(user);await db.SaveChangesAsync();return NoContent();}
 [HttpPost("admin/access"),EnableRateLimiting("admin-login")] public async Task<IActionResult> ValidateAdminAccess([FromBody]AdminAccessInput input){var credential=await db.AdminCredentials.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==1);return credential is not null&&AdminCodeHash.Verify(input.AccessCode,credential.AccessCodeHash)?Ok(new{authorized=true}):Unauthorized();}
 [HttpPost("admin/change-codes"),EnableRateLimiting("admin-login")] public async Task<IActionResult> ChangeAdminCodes([FromBody]AdminChangeCodesInput input){if(!System.Text.RegularExpressions.Regex.IsMatch(input.NewAccessCode,@"^\d{6}$")||!System.Text.RegularExpressions.Regex.IsMatch(input.NewChangeCode,@"^\d{4}$"))return BadRequest("O novo código de acesso deve ter 6 dígitos e o de confirmação, 4.");var credential=await db.AdminCredentials.SingleOrDefaultAsync(x=>x.Id==1);if(credential is null||!AdminCodeHash.Verify(input.CurrentChangeCode,credential.ChangeCodeHash))return Unauthorized(new{message="Senha incorreta! Alterações não executadas!"});credential.AccessCodeHash=AdminCodeHash.Create(input.NewAccessCode);credential.ChangeCodeHash=AdminCodeHash.Create(input.NewChangeCode);credential.SessionKey=AdminSessionTokens.NewSigningKey();credential.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync();return NoContent();}
 [HttpGet("services")] public async Task<IActionResult> Services()=>Ok(await db.Services.Where(x=>x.Active).OrderBy(x=>x.Category).ThenBy(x=>x.Name).ToListAsync());
 [HttpGet("clients")] public async Task<IActionResult> Clients()=>Ok(await db.Clients.OrderBy(x=>x.Name).ToListAsync());
 [HttpGet("clients/{id:long}/records")] public async Task<IActionResult> ClientRecords(long id){var client=await db.Clients.FindAsync(id);if(client is null)return NotFound();var appointments=await db.Appointments.Include(a=>a.Items).Include(a=>a.Record).Where(a=>a.ClientId==id).OrderByDescending(a=>a.StartsAt).ToListAsync();return Ok(new{client=new{id=client.Id,client.Name,client.Phone},appointments=appointments.Select(a=>new{id=a.Id,a.StartsAt,a.Status,items=a.Items.Select(i=>new{i.Description,i.Quantity,i.UnitPrice}),record=a.Record is null?null:new{a.Record.Id,a.Record.Markings,a.Record.Observations,a.Record.UpdatedAt}})});}
 [HttpPut("appointments/{id:long}/record")] public async Task<IActionResult> UpdateAppointmentRecord(long id,[FromBody]UpdateAppointmentRecordInput input){var appointment=await db.Appointments.Include(a=>a.Record).SingleOrDefaultAsync(a=>a.Id==id);if(appointment is null)return NotFound();var record=appointment.Record;if(record is null){record=new AppointmentRecord{AppointmentId=id};db.AppointmentRecords.Add(record);appointment.Record=record;}record.Markings=(input.Markings??"").Trim();record.Observations=(input.Observations??"").Trim();record.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync();return Ok(new{id=record.Id,record.Markings,record.Observations,record.UpdatedAt});}
 [HttpPost("clients")] public async Task<IActionResult> CreateClient(Client c){c.Id=0;if(string.IsNullOrWhiteSpace(c.Name))return BadRequest("Nome é obrigatório.");db.Clients.Add(c);await db.SaveChangesAsync();return Created($"/api/clients/{c.Id}",c);}
 [HttpGet("products")] public async Task<IActionResult> Products()=>Ok(await db.Products.OrderBy(x=>x.Name).ToListAsync());
 [HttpPost("products")] public async Task<IActionResult> CreateProduct(Product p){if(!CanManageCatalog)return Forbid();if(!await HasCatalogMutationAuthorization())return Unauthorized();if(string.IsNullOrWhiteSpace(p.Name)||p.Price<=0||p.Stock<0)return BadRequest("Informe nome, preço positivo e estoque não negativo.");p.Id=0;p.Name=p.Name.Trim();db.Products.Add(p);await db.SaveChangesAsync();return Created($"/api/products/{p.Id}",p);}
 [HttpPost("services")] public async Task<IActionResult> CreateService([FromBody]CreateCatalogServiceInput input){if(!CanManageCatalog)return Forbid();if(!await HasCatalogMutationAuthorization())return Unauthorized();if(string.IsNullOrWhiteSpace(input.Category)||string.IsNullOrWhiteSpace(input.Name)||input.Price<=0)return BadRequest("Informe categoria, nome e preço positivo para o serviço.");var service=new CatalogService{Category=input.Category.Trim(),Name=input.Name.Trim(),Variant=string.IsNullOrWhiteSpace(input.Variant)?null:input.Variant.Trim(),HairLength=string.IsNullOrWhiteSpace(input.HairLength)?null:input.HairLength.Trim(),Price=input.Price,PriceIsStartingAt=input.PriceIsStartingAt};db.Services.Add(service);await db.SaveChangesAsync();return Created($"/api/services/{service.Id}",service);}
 [HttpPatch("products/{id:long}")] public async Task<IActionResult> UpdateProduct(long id,[FromBody]UpdateProductInput input){if(!CanManageCatalog&&!CanChangePrices)return Forbid();var p=await db.Products.FindAsync(id);if(p is null)return NotFound();if(!await HasCatalogMutationAuthorization())return Unauthorized();if(string.IsNullOrWhiteSpace(input.Name)||input.Price<=0||input.Stock<0)return BadRequest("Informe nome, preço positivo e estoque não negativo.");if(!CanChangePrices&&input.Price!=p.Price)return Forbid();if(!CanManageCatalog&&input.Stock!=p.Stock)return Forbid();p.Name=input.Name.Trim();p.Price=input.Price;p.Stock=input.Stock;await db.SaveChangesAsync();return Ok(p);}
 [HttpDelete("products/{id:long}")] public async Task<IActionResult> DeleteProduct(long id){if(!CanManageCatalog)return Forbid();if(!await HasCatalogMutationAuthorization())return Unauthorized();var p=await db.Products.FindAsync(id);if(p is null)return NotFound();var pendingUse=await db.AppointmentItems.AnyAsync(i=>i.ProductId==id&&db.Appointments.Any(a=>a.Id==i.AppointmentId&&a.Status=="Agendado"));if(pendingUse)return Conflict("Este produto está em um agendamento pendente e não pode ser excluído.");var historicalItems=await db.AppointmentItems.Where(i=>i.ProductId==id).ToListAsync();foreach(var item in historicalItems)item.ProductId=null;db.Products.Remove(p);await db.SaveChangesAsync();return NoContent();}
 [HttpPatch("services/{id:long}")] public async Task<IActionResult> UpdateServicePrice(long id,[FromBody]UpdateServicePriceInput input){if(!CanChangePrices)return Forbid();if(!await HasCatalogMutationAuthorization())return Unauthorized(new{message="Senha de confirmação incorreta."});var service=await db.Services.SingleOrDefaultAsync(x=>x.Id==id&&x.Active);if(service is null)return NotFound();if(input.Price<=0)return BadRequest("Informe um preço positivo.");if(input.Category is not null&&string.IsNullOrWhiteSpace(input.Category)||input.Name is not null&&string.IsNullOrWhiteSpace(input.Name))return BadRequest("Informe o nome e o tipo do serviço.");service.Price=input.Price;if(input.Category is not null)service.Category=input.Category.Trim();if(input.Name is not null)service.Name=input.Name.Trim();if(input.Variant is not null)service.Variant=string.IsNullOrWhiteSpace(input.Variant)?null:input.Variant.Trim();if(input.HairLength is not null)service.HairLength=string.IsNullOrWhiteSpace(input.HairLength)?null:input.HairLength.Trim();if(input.PriceIsStartingAt is not null)service.PriceIsStartingAt=input.PriceIsStartingAt.Value;await db.SaveChangesAsync();return Ok(service);}
 [HttpDelete("services/{id:long}")] public async Task<IActionResult> DeleteService(long id){if(!CanManageCatalog)return Forbid();if(!await HasCurrentUserAccessCode())return Unauthorized(new{message="Senha de acesso incorreta. Serviço não excluído."});var service=await db.Services.SingleOrDefaultAsync(x=>x.Id==id&&x.Active);if(service is null)return NotFound();service.Active=false;await db.SaveChangesAsync();return NoContent();}
 [HttpGet("monthly-packages")] public async Task<IActionResult> MonthlyPackages(){var packages=await db.MonthlyPackages.Include(x=>x.Client).Include(x=>x.Items).Include(x=>x.Sessions).Include(x=>x.Payments).OrderByDescending(x=>x.Month).ThenBy(x=>x.Client!.Name).ToListAsync();return Ok(packages.Select(x=>new{id=x.Id,x.ClientId,client=new{id=x.Client!.Id,x.Client.Name,x.Client.Phone},x.Month,x.Price,x.Completed,x.CancelledAt,paidAmount=x.Payments.Sum(p=>p.Amount),balance=Math.Max(0,x.Price-x.Payments.Sum(p=>p.Amount)),x.CreatedAt,services=x.Items.Select(i=>new{id=i.Id,serviceId=i.ServiceId,name=i.Description}),sessions=x.Sessions.OrderBy(s=>s.Number).Select(s=>new{id=s.Id,number=s.Number,s.Completed,s.CompletedAt}),payments=x.Payments.OrderBy(p=>p.ReceivedAt).Select(p=>new{id=p.Id,p.Amount,p.PaymentMethod,p.ReceivedAt})}));}
 [HttpPost("monthly-packages")] public async Task<IActionResult> CreateMonthlyPackage([FromBody]CreateMonthlyPackageInput input){if(!await HasCurrentUserAccessCode())return Unauthorized(new{message="Senha de acesso incorreta. Pacote não cadastrado."});if(input.Price<=0||input.InitialPayment<=0||input.InitialPayment>input.Price)return BadRequest("Informe um valor inicial maior que zero e até o preço do pacote.");if(input.InitialPayment>0&&!ValidMethod(input.PaymentMethod))return BadRequest("Escolha Pix, Débito ou Crédito.");var client=await db.Clients.FindAsync(input.ClientId);if(client is null)return BadRequest("Cliente não encontrado.");var previous=await db.MonthlyPackages.Include(x=>x.Payments).Where(x=>x.ClientId==input.ClientId&&x.CancelledAt==null).ToListAsync();var outstanding=previous.Sum(x=>Math.Max(0,x.Price-x.Payments.Sum(p=>p.Amount)));if(outstanding>0)return Conflict($"Não é possível abrir outro pacote: {client.Name} possui {outstanding.ToString("C",System.Globalization.CultureInfo.GetCultureInfo("pt-BR"))} em aberto. Quite o saldo primeiro.");if(input.ServiceIds.Count==0)return BadRequest("Selecione ao menos um serviço para o pacote.");var services=await db.Services.Where(x=>input.ServiceIds.Contains(x.Id)&&x.Active).ToListAsync();if(services.Count!=input.ServiceIds.Distinct().Count())return BadRequest("Um ou mais serviços selecionados não existem mais.");var month=new DateOnly(input.Month.Year,input.Month.Month,1);var package=new MonthlyServicePackage{ClientId=input.ClientId,Month=month,Price=input.Price,Items=services.Select(s=>new MonthlyPackageItem{ServiceId=s.Id,Description=s.Name+(s.Variant is null?"":$" · {s.Variant}")+(s.HairLength is null?"":$" · {s.HairLength}")}).ToList(),Sessions=Enumerable.Range(1,4).Select(n=>new MonthlyPackageSession{Number=n}).ToList()};if(input.InitialPayment>0)package.Payments.Add(new(){Amount=input.InitialPayment,PaymentMethod=input.PaymentMethod,ReceivedAt=DateTime.UtcNow});db.MonthlyPackages.Add(package);await db.SaveChangesAsync();return Created($"/api/monthly-packages/{package.Id}",new{id=package.Id,completed=false,balance=package.Price-input.InitialPayment});}
 [HttpPost("monthly-packages/{id:long}/payments")] public async Task<IActionResult> AddMonthlyPackagePayment(long id,[FromBody]AddMonthlyPackagePaymentInput input){if(!await HasCurrentUserAccessCode())return Unauthorized(new{message="Senha de acesso incorreta."});if(input.Amount<=0||!ValidMethod(input.PaymentMethod))return BadRequest("Informe um valor positivo e escolha Pix, Débito ou Crédito.");var package=await db.MonthlyPackages.Include(x=>x.Payments).SingleOrDefaultAsync(x=>x.Id==id);if(package is null)return NotFound();if(package.CancelledAt is not null)return Conflict("Um pacote cancelado não aceita novos recebimentos.");var balance=Math.Max(0,package.Price-package.Payments.Sum(p=>p.Amount));if(balance<=0)return Conflict("Este pacote já está quitado.");if(input.Amount>balance)return BadRequest($"O recebimento não pode ultrapassar o saldo de {balance.ToString("C",System.Globalization.CultureInfo.GetCultureInfo("pt-BR"))}.");var payment=new MonthlyPackagePayment{PackageId=id,Amount=input.Amount,PaymentMethod=input.PaymentMethod,ReceivedAt=DateTime.UtcNow};db.MonthlyPackagePayments.Add(payment);await db.SaveChangesAsync();var remaining=balance-input.Amount;return Ok(new{paidAmount=package.Price-remaining,balance=remaining,paid=remaining==0,payment=new{id=payment.Id,payment.Amount,payment.PaymentMethod,payment.ReceivedAt}});}
 [HttpPatch("monthly-packages/{id:long}/services")] public async Task<IActionResult> UpdateMonthlyPackageServices(long id,[FromBody]UpdateMonthlyPackageServicesInput input){if(!await HasCurrentUserAccessCode())return Unauthorized(new{message="Senha de acesso incorreta."});var package=await db.MonthlyPackages.Include(x=>x.Items).SingleOrDefaultAsync(x=>x.Id==id);if(package is null)return NotFound();if(package.CancelledAt is not null)return Conflict("Um pacote cancelado não pode ser alterado.");if(package.Completed)return Conflict("O pacote foi concluído e não pode mais ser alterado.");if(input.ServiceIds.Count==0)return BadRequest("Mantenha ao menos um serviço no pacote.");var ids=input.ServiceIds.Distinct().ToArray();var services=await db.Services.Where(x=>ids.Contains(x.Id)&&x.Active).ToListAsync();if(services.Count!=ids.Length)return BadRequest("Um ou mais serviços selecionados não existem mais.");db.MonthlyPackageItems.RemoveRange(package.Items);package.Items=services.Select(s=>new MonthlyPackageItem{PackageId=id,ServiceId=s.Id,Description=s.Name+(s.Variant is null?"":$" · {s.Variant}")+(s.HairLength is null?"":$" · {s.HairLength}")}).ToList();await db.SaveChangesAsync();return NoContent();}
 [HttpPatch("monthly-packages/{id:long}")] public async Task<IActionResult> UpdateMonthlyPackage(long id,[FromBody]UpdateMonthlyPackageInput input){if(!await HasCurrentUserAccessCode())return Unauthorized(new{message="Senha de acesso incorreta. Pacote não alterado."});if(input.Price<=0)return BadRequest("Informe um preço positivo para o pacote.");if(input.ServiceIds is null||input.ServiceIds.Count==0)return BadRequest("Mantenha ao menos um serviço no pacote.");var package=await db.MonthlyPackages.Include(x=>x.Items).Include(x=>x.Payments).Include(x=>x.Sessions).SingleOrDefaultAsync(x=>x.Id==id);if(package is null)return NotFound();if(package.CancelledAt is not null)return Conflict("Um pacote cancelado não pode ser alterado.");if(package.Completed)return Conflict("Pacotes concluídos não podem mais ser alterados.");var received=package.Payments.Sum(p=>p.Amount);if(input.Price<received)return Conflict("O preço do pacote não pode ser menor que o valor já recebido.");var ids=input.ServiceIds.Distinct().ToArray();var services=await db.Services.Where(s=>ids.Contains(s.Id)&&s.Active).ToListAsync();if(services.Count!=ids.Length)return BadRequest("Um ou mais serviços selecionados não existem mais.");db.MonthlyPackageItems.RemoveRange(package.Items);package.Items=services.Select(s=>new MonthlyPackageItem{PackageId=id,ServiceId=s.Id,Description=s.Name+(s.Variant is null?"":$" · {s.Variant}")+(s.HairLength is null?"":$" · {s.HairLength}")}).ToList();package.Price=input.Price;package.Month=new DateOnly(input.Month.Year,input.Month.Month,1);await db.SaveChangesAsync();return Ok(new{id=package.Id,package.Price,package.Month,balance=Math.Max(0,package.Price-received)});}
 [HttpDelete("monthly-packages/{id:long}")] public async Task<IActionResult> DeleteMonthlyPackage(long id){if(!await HasCurrentUserAccessCode())return Unauthorized(new{message="Senha de acesso incorreta. Pacote não excluído."});var package=await db.MonthlyPackages.SingleOrDefaultAsync(x=>x.Id==id);if(package is null)return NotFound();if(package.CancelledAt is not null)return Conflict("Este pacote já foi cancelado.");package.CancelledAt=DateTime.UtcNow;await db.SaveChangesAsync();return NoContent();}
 [HttpPatch("monthly-packages/{id:long}/sessions/{number:int}")] public async Task<IActionResult> UpdateMonthlyPackageSession(long id,int number,[FromBody]UpdateMonthlyPackageSessionInput input){if(!await HasCurrentUserAccessCode())return Unauthorized(new{message="Senha de acesso incorreta."});if(number<1||number>4)return BadRequest("A sessão deve estar entre 1 e 4.");var package=await db.MonthlyPackages.Include(x=>x.Sessions).Include(x=>x.Payments).SingleOrDefaultAsync(x=>x.Id==id);if(package is null)return NotFound();if(package.CancelledAt is not null)return Conflict("Um pacote cancelado não pode ser alterado.");var session=package.Sessions.SingleOrDefault(x=>x.Number==number);if(session is null)return NotFound();session.Completed=input.Completed;session.CompletedAt=input.Completed?DateTime.UtcNow:null;package.Completed=package.Sessions.All(x=>x.Completed);var balance=Math.Max(0,package.Price-package.Payments.Sum(p=>p.Amount));await db.SaveChangesAsync();return Ok(new{id=package.Id,package.Completed,paidAmount=package.Price-balance,balance,fullyPaid=balance==0,renewalAllowed=package.Completed&&balance==0,renewalPrompt=package.Completed});}
 [HttpGet("appointments")] public async Task<IActionResult> Appointments([FromQuery]DateOnly? from,[FromQuery]DateOnly? to){var q=db.Appointments.Include(a=>a.Client).Include(a=>a.Items).Include(a=>a.Receivables).AsQueryable();if(from is not null){var start=BrazilDayStartUtc(from.Value);q=q.Where(a=>a.StartsAt>=start);}if(to is not null){var end=BrazilDayStartUtc(to.Value.AddDays(1));q=q.Where(a=>a.StartsAt<end);}var rows=await q.OrderBy(a=>a.StartsAt).ToListAsync();return Ok(rows.Select(a=>new{id=a.Id,a.ClientId,client=new{id=a.Client!.Id,a.Client.Name,a.Client.Phone},a.StartsAt,a.Status,a.BookingFeePaid,items=a.Items.Select(i=>new{i.Id,i.ServiceId,i.ProductId,i.Description,i.UnitPrice,i.Quantity}),receivables=a.Receivables.Select(r=>new{r.Id,r.Amount,r.InstallmentNumber,r.DueDate,r.Paid,r.PaymentMethod,r.PaidAt})}));}
 [HttpPost("appointments")] public async Task<IActionResult> CreateAppointment(CreateAppointment input){
  if(input.Items.Count==0)return BadRequest("Informe ao menos um serviço ou produto."); if(!await db.Clients.AnyAsync(c=>c.Id==input.ClientId))return BadRequest("Cliente não encontrado.");
  var startsAt=input.StartsAt.Kind==DateTimeKind.Unspecified?new DateTimeOffset(input.StartsAt,TimeSpan.FromHours(-3)).UtcDateTime:input.StartsAt.ToUniversalTime(); var lines=new List<AppointmentItem>(); foreach(var i in input.Items){var price=i.UnitPrice;if(i.ServiceId is long sid){var s=await db.Services.FindAsync(sid);if(s is null)return BadRequest("Serviço não encontrado.");price??=s.Price;lines.Add(new(){ServiceId=sid,Description=s.Name+(s.Variant is null?"":$" ({s.Variant})")+(s.HairLength is null?"":$" ({s.HairLength})"),UnitPrice=price.Value,Quantity=Math.Max(1,i.Quantity)});}else if(i.ProductId is long pid){var p=await db.Products.FindAsync(pid);if(p is null)return BadRequest("Produto não encontrado.");price??=p.Price;if(p.Stock<Math.Max(1,i.Quantity))return BadRequest($"Estoque insuficiente para {p.Name}.");p.Stock-=Math.Max(1,i.Quantity);lines.Add(new(){ProductId=pid,Description=p.Name,UnitPrice=price.Value,Quantity=Math.Max(1,i.Quantity)});}else if(price is not null)lines.Add(new(){Description=i.Description??"Item avulso",UnitPrice=price.Value,Quantity=Math.Max(1,i.Quantity)});else return BadRequest("Item inválido.");}
  var total=lines.Sum(x=>x.UnitPrice*x.Quantity);var a=new Appointment{ClientId=input.ClientId,StartsAt=startsAt,Items=lines,BookingFeePaid=input.BookingFeePaid,Record=new AppointmentRecord{Markings="",Observations="",UpdatedAt=DateTime.UtcNow}};if(input.BookingFeePaid)a.Receivables.Add(new(){Amount=Math.Min(30m,total),InstallmentNumber=0,DueDate=DateOnly.FromDateTime(DateTime.UtcNow.AddHours(-3)),Paid=true,PaymentMethod="Sinal",PaidAt=DateTime.UtcNow});db.Appointments.Add(a);await db.SaveChangesAsync();return Created($"/api/appointments/{a.Id}",new{id=a.Id,total,bookingFeePaid=a.BookingFeePaid,recordId=a.Record.Id});
 }
 [HttpPatch("appointments/{id:long}/items")]
 public async Task<IActionResult> UpdateAppointmentItems(long id,[FromBody] List<SaleItemInput> items){
  if(items is null||items.Count==0)return BadRequest("Mantenha pelo menos um servico ou produto no agendamento.");
  var appointment=await db.Appointments.Include(a=>a.Items).Include(a=>a.Receivables).SingleOrDefaultAsync(a=>a.Id==id);
  if(appointment is null)return NotFound();
  if(appointment.Status!="Agendado")return Conflict("Somente agendamentos pendentes podem ser editados.");
  if(appointment.Receivables.Any(r=>r.Paid&&r.InstallmentNumber!=0))return Conflict("Nao e possivel alterar os itens depois que uma parcela foi paga.");
  var lines=new List<AppointmentItem>();
  foreach(var item in items){
   var quantity=Math.Max(1,item.Quantity);
   if(item.ServiceId is long serviceId&&item.ProductId is null){var service=await db.Services.FindAsync(serviceId);if(service is null)return BadRequest("Servico nao encontrado.");var description=service.Name+(service.Variant is null?"":$" ({service.Variant})")+(service.HairLength is null?"":$" ({service.HairLength})");lines.Add(new(){AppointmentId=id,ServiceId=serviceId,Description=description,UnitPrice=service.Price,Quantity=quantity});}
   else if(item.ProductId is long productId&&item.ServiceId is null){var product=await db.Products.FindAsync(productId);if(product is null)return BadRequest("Produto nao encontrado.");lines.Add(new(){AppointmentId=id,ProductId=productId,Description=product.Name,UnitPrice=product.Price,Quantity=quantity});}
   else if(item.ServiceId is null&&item.ProductId is null&&item.UnitPrice is >0){lines.Add(new(){AppointmentId=id,Description=item.Description??"Item avulso",UnitPrice=item.UnitPrice.Value,Quantity=quantity});}
   else return BadRequest("Cada item deve indicar um servico ou produto valido.");
  }
  var oldProducts=appointment.Items.Where(i=>i.ProductId is not null).GroupBy(i=>i.ProductId!.Value).ToDictionary(g=>g.Key,g=>g.Sum(i=>i.Quantity));
  var newProducts=lines.Where(i=>i.ProductId is not null).GroupBy(i=>i.ProductId!.Value).ToDictionary(g=>g.Key,g=>g.Sum(i=>i.Quantity));
  foreach(var productId in oldProducts.Keys.Union(newProducts.Keys)){var product=await db.Products.FindAsync(productId);if(product is null)return BadRequest("Produto nao encontrado.");var delta=oldProducts.GetValueOrDefault(productId)-newProducts.GetValueOrDefault(productId);if(delta<0&&product.Stock < -delta)return BadRequest($"Estoque insuficiente para {product.Name}.");product.Stock+=delta;}
  db.AppointmentItems.RemoveRange(appointment.Items);appointment.Items=lines;
  var installments=appointment.Receivables.Where(r=>r.InstallmentNumber>0&&!r.Paid).OrderBy(r=>r.InstallmentNumber).ToList();
  var total=lines.Sum(i=>i.UnitPrice*i.Quantity);if(installments.Count>0){var installmentValue=Math.Round(total/installments.Count,2);for(var index=0;index<installments.Count;index++)installments[index].Amount=index==installments.Count-1?total-installmentValue*(installments.Count-1):installmentValue;}
  await db.SaveChangesAsync();return Ok(new{id=appointment.Id,total,items=lines.Select(i=>new{i.Description,i.UnitPrice,i.Quantity}),installments=installments.Select(r=>new{r.InstallmentNumber,r.Amount,r.DueDate})});
 }
 [HttpDelete("appointments/{id:long}")] public async Task<IActionResult> DeleteAppointment(long id){if(!await HasCurrentUserAccessCode())return Unauthorized(new{message="Senha de acesso incorreta. Agendamento não excluído."});var appointment=await db.Appointments.Include(x=>x.Items).Include(x=>x.Receivables).SingleOrDefaultAsync(x=>x.Id==id);if(appointment is null)return NotFound();foreach(var item in appointment.Items.Where(x=>x.ProductId is not null)){var product=await db.Products.FindAsync(item.ProductId);if(product is not null)product.Stock+=item.Quantity;}db.Appointments.Remove(appointment);await db.SaveChangesAsync();return NoContent();}
 [HttpGet("dashboard")] public async Task<IActionResult> Dashboard(){var today=DateOnly.FromDateTime(DateTime.UtcNow.AddHours(-3));var due=await db.Receivables.Include(r=>r.Appointment!).ThenInclude(a=>a.Client).Where(r=>!r.Paid&&r.DueDate==today.AddDays(1)).OrderBy(r=>r.Appointment!.Client!.Name).ToListAsync();var start=BrazilDayStartUtc(today);var end=BrazilDayStartUtc(today.AddDays(1));var todayAppointments=await db.Appointments.CountAsync(a=>a.StartsAt>=start&&a.StartsAt<end);var appointmentRevenue=await db.Receivables.Where(r=>r.Paid&&r.PaidAt!=null&&r.PaidAt>=start&&r.PaidAt<end).SumAsync(r=>(decimal?)r.Amount)??0m;var packageRevenue=await db.MonthlyPackagePayments.Where(p=>p.ReceivedAt>=start&&p.ReceivedAt<end&&p.Package!.CancelledAt==null).SumAsync(p=>(decimal?)p.Amount)??0m;return Ok(new{tomorrow=due.Select(r=>new{r.Id,r.Amount,r.InstallmentNumber,r.DueDate,client=r.Appointment!.Client!.Name}),todayAppointments,todayRevenue=appointmentRevenue+packageRevenue});}
 [HttpPatch("receivables/{id:long}/paid")] public async Task<IActionResult> MarkPaid(long id,[FromBody]MarkReceivablePaidInput input){var r=await db.Receivables.FindAsync(id);if(r is null)return NotFound();if(!ValidMethod(input.PaymentMethod))return BadRequest("Escolha Pix, Débito ou Crédito.");r.Paid=true;r.PaymentMethod=input.PaymentMethod;r.PaidAt=DateTime.UtcNow;await db.SaveChangesAsync();return NoContent();}
 [HttpGet("reports")] public async Task<IActionResult> Reports([FromQuery]DateOnly from,[FromQuery]DateOnly to){var a=BrazilDayStartUtc(from);var b=BrazilDayStartUtc(to.AddDays(1));var appointments=await db.Appointments.CountAsync(x=>x.Status=="Concluído"&&x.StartsAt>=a&&x.StartsAt<b);var revenue=await db.Receivables.Where(r=>r.Paid&&r.PaidAt!=null&&r.PaidAt>=a&&r.PaidAt<b).SumAsync(r=>(decimal?)r.Amount)??0m;return Ok(new{appointments,revenue,from,to});}
 [HttpPost("appointments/{id:long}/checkout")]
 public async Task<IActionResult> Checkout(long id,[FromBody]CheckoutInput input){
  var a=await db.Appointments.Include(x=>x.Items).Include(x=>x.Receivables).SingleOrDefaultAsync(x=>x.Id==id);
  if(a is null)return NotFound();if(a.Status!="Agendado")return Conflict("Este agendamento já foi concluído.");
  var total=a.Items.Sum(i=>i.UnitPrice*i.Quantity);var paid=a.Receivables.Where(r=>r.Paid).Sum(r=>r.Amount);var balance=Math.Max(0,total-paid);var today=DateOnly.FromDateTime(DateTime.UtcNow.AddHours(-3));
  decimal deferredTotal=0;
  if(input.Mode=="paid"){
   if(!ValidMethod(input.PaymentMethod))return BadRequest("Escolha Pix, Débito ou Crédito.");
   if(balance>0)a.Receivables.Add(new(){Amount=balance,InstallmentNumber=1,DueDate=today,Paid=true,PaymentMethod=input.PaymentMethod,PaidAt=DateTime.UtcNow});
  }else if(input.Mode=="deferred"){
   var parts=input.Installments??[];
   if(parts.Count is <1 or >5||parts.Any(p=>p.Amount<=0||p.DueDate<today))return BadRequest("Informe de 1 a 5 parcelas positivas com vencimento válido.");
   if(parts.Count(p=>p.IsEntry)>1||parts.Select((p,index)=>(p,index)).Any(x=>x.p.IsEntry&&x.index!=0))return BadRequest("A entrada deve ser única e ser a primeira parcela.");
   if(parts.Any(p=>p.IsEntry&&p.DueDate!=today))return BadRequest("A entrada vence na data do atendimento.");
   var totalCents=decimal.ToInt64(decimal.Round(balance*100m,0,MidpointRounding.AwayFromZero));var hasEntry=parts[0].IsEntry;if(hasEntry&&parts.Count<2)return BadRequest("Com entrada, informe ao menos uma parcela futura.");var entryCents=hasEntry?decimal.ToInt64(decimal.Round(parts[0].Amount*100m,0,MidpointRounding.AwayFromZero)):0;if(entryCents>=totalCents&&hasEntry)return BadRequest("A entrada deve ser menor que o saldo para permitir o parcelamento.");var financedCents=totalCents-entryCents;var futureCount=parts.Count-(hasEntry?1:0);var rate=parts.Count>2?0.03m:0m;decimal installmentAmount;
   if(rate==0)installmentAmount=decimal.Round((financedCents/100m)/futureCount,2,MidpointRounding.AwayFromZero);
   else{var discount=(decimal)Math.Pow((double)(1m+rate),-futureCount);installmentAmount=decimal.Round((financedCents/100m)*rate/(1m-discount),2,MidpointRounding.AwayFromZero);}
   for(var index=0;index<parts.Count;index++){
    var expected=hasEntry&&index==0?entryCents/100m:installmentAmount;
    if(Math.Abs(parts[index].Amount-expected)>0.01m)return BadRequest("Os valores das parcelas foram alterados. Confira o plano recalculado na tela.");
    deferredTotal+=parts[index].Amount;
   }
   db.Receivables.RemoveRange(a.Receivables.Where(r=>!r.Paid));
   for(var index=0;index<parts.Count;index++)a.Receivables.Add(new(){Amount=parts[index].Amount,InstallmentNumber=index+1,DueDate=parts[index].DueDate,Paid=false});
  }else return BadRequest("Opção de pagamento inválida.");
  a.Status="Concluído";await db.SaveChangesAsync();
  return Ok(new{id=a.Id,total,paid=paid+(input.Mode=="paid"?balance:0),outstanding=input.Mode=="paid"?0:deferredTotal});
 }
 [HttpGet("clients/{id:long}/financial")] public async Task<IActionResult> ClientFinancial(long id){var c=await db.Clients.FindAsync(id);if(c is null)return NotFound();var rows=await db.Appointments.Include(a=>a.Items).Include(a=>a.Receivables).Where(a=>a.ClientId==id).OrderByDescending(a=>a.StartsAt).ToListAsync();return Ok(new{client=new{id=c.Id,c.Name,c.Phone},appointments=rows.Select(a=>new{id=a.Id,a.StartsAt,a.Status,total=a.Items.Sum(i=>i.UnitPrice*i.Quantity),paid=a.Receivables.Where(r=>r.Paid).Sum(r=>r.Amount),outstanding=(a.Receivables.Where(r=>!r.Paid).Sum(r=>r.Amount)>0?a.Receivables.Where(r=>!r.Paid).Sum(r=>r.Amount):Math.Max(0,a.Items.Sum(i=>i.UnitPrice*i.Quantity)-a.Receivables.Where(r=>r.Paid).Sum(r=>r.Amount))),items=a.Items.Select(i=>new{i.Description,i.UnitPrice,i.Quantity}),payments=a.Receivables.OrderBy(r=>r.DueDate).Select(r=>new{r.Id,r.Amount,r.InstallmentNumber,r.DueDate,r.Paid,r.PaymentMethod,r.PaidAt})})});}
 private static bool ValidMethod(string? method)=>method is "Pix" or "Débito" or "Crédito";
 [HttpPatch("appointments/{id:long}/complete")] public IActionResult Complete(long id)=>BadRequest("Use a tela de fechamento para registrar o pagamento ou as datas das parcelas.");
}
